+// Multi-tool shared-store MCP server.
+//
+// Tools implemented:
+//   item_create  - create an item, generate id like i1, i2, ... in creation order
+//   item_update  - update an item, preserving unspecified fields
+//   item_get     - return a single item by id
+//   item_list    - return all items in creation order
+//
+// All tools share an in-memory store. Strings are validated, unknown tools are
+// rejected, and every inputSchema uses additionalProperties: false.
+
+const store = new Map();      // item_id -> item object
+const order = [];             // item_ids in creation order
+let counter = 0;              // id counter
+
+function nextId() {
+  counter += 1;
+  return `i${counter}`;
+}
+
+function assertNonEmptyString(value, name) {
+  if (typeof value !== 'string' || value.length === 0) {
+    const error = new Error(`Invalid argument: ${name} must be a non-empty string`);
+    error.code = -32602;
+    throw error;
+  }
+}
+
+function toResult(obj) {
+  return { content: [{ type: 'text', text: JSON.stringify(obj) }] };
+}
+
+function notFound(itemId) {
+  const error = new Error(`Item not found: ${itemId}`);
+  error.code = -32602;
+  throw error;
+}
+
+const TOOLS = [
+  {
+    name: 'item_create',
+    description: 'Create a new item. Returns the created item with a generated item_id (i1, i2, ...).',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        name: { type: 'string', description: 'Name of the item.' }
+      },
+      required: ['name'],
+      additionalProperties: false
+    }
+  },
+  {
+    name: 'item_update',
+    description: 'Update an existing item by item_id. Unspecified fields are preserved.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        item_id: { type: 'string', description: 'ID of the item to update.' },
+        name: { type: 'string', description: 'New name for the item.' },
+        tag: { type: 'string', description: 'Tag to set on the item.' }
+      },
+      required: ['item_id'],
+      additionalProperties: false
+    }
+  },
+  {
+    name: 'item_get',
+    description: 'Get a single item by item_id.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        item_id: { type: 'string', description: 'ID of the item to retrieve.' }
+      },
+      required: ['item_id'],
+      additionalProperties: false
+    }
+  },
+  {
+    name: 'item_list',
+    description: 'List all items in creation order.',
+    inputSchema: {
+      type: 'object',
+      properties: {},
+      required: [],
+      additionalProperties: false
+    }
+  }
+];
+
+export async function listTools() {
+  return TOOLS.map(({ name, description, inputSchema }) => ({ name, description, inputSchema }));
+}
+
+export async function callTool(name, args = {}) {
+  const tool = TOOLS.find((t) => t.name === name);
+  if (!tool) {
+    const error = new Error(`Unknown tool: ${name}`);
+    error.code = -32601;
+    throw error;
+  }
+
+  switch (name) {
+    case 'item_create': {
+      assertNonEmptyString(args.name, 'name');
+      const itemId = nextId();
+      const item = { item_id: itemId, name: args.name };
+      store.set(itemId, item);
+      order.push(itemId);
+      return toResult(item);
+    }
+    case 'item_update': {
+      assertNonEmptyString(args.item_id, 'item_id');
+      const existing = store.get(args.item_id);
+      if (!existing) notFound(args.item_id);
+      const updated = { ...existing };
+      if (args.name !== undefined) {
+        assertNonEmptyString(args.name, 'name');
+        updated.name = args.name;
+      }
+      if (args.tag !== undefined) {
+        assertNonEmptyString(args.tag, 'tag');
+        updated.tag = args.tag;
+      }
+      store.set(args.item_id, updated);
+      return toResult(updated);
+    }
+    case 'item_get': {
+      assertNonEmptyString(args.item_id, 'item_id');
+      const existing = store.get(args.item_id);
+      if (!existing) notFound(args.item_id);
+      return toResult(existing);
+    }
+    case 'item_list': {
+      const items = order.map((id) => store.get(id));
+      return toResult(items);
+    }
+    default: {
+      const error = new Error(`Unknown tool: ${name}`);
+      error.code = -32601;
+      throw error;
+    }
+  }
